    public function testLookupUser()
    {
//        $faker = \Faker\Factory::create();
//        $token = $faker->sha256();
        $token = \Faker\Factory::create()->sha256();
        $userid = 45;
        $this->userdao->set_response($userid);
        $this->object->set_user_table_access($this->userdao);
        $this->object->lookupUser($token);

        $this->assertAttributeNotEmpty('user', $this->object);
        $this->assertAttributeInstanceOf('\App\classes\UserManagement\models\ISettableUser', 'user', $this->object);
        $this->assertEquals('retrieve_userid_from_token', $this->userdao->called);
        $this->assertEquals($token, $this->userdao->called_list[0][1][0]);
    }

