    public function testMakeCredentials()
    {
        $user = new SettableUser();
        $user->set_id(2);
        $this->cred_gen->username = self::$username;
        $this->cred_gen->password = self::$password;
        $this->cred_gen->db_name = self::$dbname;
        $this->object->set_credential_generator($this->cred_gen);
        $this->object->user = $user;
        $this->object->setWatcher($this->watcher);

        $this->object->makeCredentials();
        $this->assertEquals(self::$username, $user->get_db_username());
        $this->assertEquals(self::$password, $user->get_db_password());
        $this->assertEquals(self::$username, $user->get_ro_username());
        $this->assertEquals(self::$password, $user->get_ro_password());
        $this->assertEquals(self::$dbname, $user->get_db_name());

        $this->assertEquals('update', $this->watcher->called);
        $this->assertEquals(SetupWatcher::USER_RECORD_FOUND, $this->watcher->called_list[0][1][0]);
    }

