    /**
     * @covers App\classes\UserManagement\maker\AccountSetup::run
     */
    public function testRun()
    {
        $token = \Faker\Factory::create()->sha256();
        $userid = 45;
        $this->userdao->set_response($userid);
        $this->object->set_user_table_access($this->userdao);

        $user = new SettableUser();
        $user->set_id($userid);
        $this->object->user = $user;

        $this->cred_gen->username = self::$username;
        $this->cred_gen->password = self::$password;
        $this->cred_gen->db_name = self::$dbname;
        $this->object->set_credential_generator($this->cred_gen);

        $this->object->setWatcher($this->watcher);

        $this->object->setNewDbDao($this->new_db_dao);

        //action
        $this->object->run($token);

        //assertions not covered in other tests
        $this->assertEquals(SetupWatcher::GOM_USER_COMPLETE, $this->watcher->called_list[2][1][0]);
        $this->assertTrue($this->new_db_dao->wasCalled);
        $this->assertEquals('make', $this->new_db_dao->called);
        $this->assertInstanceOf('\App\classes\UserManagement\models\ISettableUser', $this->new_db_dao->called_list[0][1][0]);

        $result_user = $this->new_db_dao->called_list[0][1][0];
        $this->assertEquals(self::$username, $result_user->get_db_username());
        $this->assertEquals(self::$password, $result_user->get_db_password());
        $this->assertEquals(self::$username, $result_user->get_ro_username());
        $this->assertEquals(self::$password, $result_user->get_ro_password());
        $this->assertEquals(self::$dbname, $result_user->get_db_name());
    }

